  "components.burning-ember.desc": "Al recoger:\nObtén un aura de daño que inflige 6 de daño de Fuego a los enemigos en un radio de 5 casillas durante 15 turnos",
  "components.burning-ember.name": "Brasa ardiente",
  "components.chaos-seed.desc": "Al forjar:\nSi el equipo forjado tiene la etiqueta Naturaleza, obtiene la etiqueta Caos\nCualquier bonificación de atributos que el equipo otorgue a los hechizos y equipo de Naturaleza también se otorga a los hechizos y equipo de Caos\nCualquier efecto que se active específicamente por hechizos de Naturaleza también se activa por hechizos de Caos",
  "components.chaos-seed.name": "Semilla del caos",
  "components.charged-cog.desc": "Al recoger:\nInvoca una Bola de Espinas de Cobre aliada",
  "components.charged-cog.name": "Engranaje cargado",
  "components.charred-relic.desc": "Al forjar:\nSi el equipo forjado tiene la etiqueta Sagrado, otorga +1 a cada uno de sus atributos base a un hechizo Sagrado aleatorio que conozcas",
  "components.charred-relic.name": "Reliquia carbonizada",
  "components.chimera-eyes.desc": "Al forjar:\nSi el equipo forjado tiene las etiquetas Caos u Ojo, Ojos de Quimera otorga una mejora aleatoria a los hechizos de Ojo que conozcas\n\nSi este componente otorga una o más mejoras, se destruye",
  "components.chimera-eyes.name": "Ojos de quimera",
  "components.crimson-sigil.desc": "Al recoger:\nLanza Pulso de Drenaje",
  "components.crimson-sigil.name": "Sello carmesí",
  "components.cursed-dice.desc": "Al recoger:\nLanza Rueda de la Muerte entre 2 y 12 veces",
  "components.cursed-dice.name": "Dados malditos",
  "components.cursed-rosary.desc": "Al forjar:\nSi el equipo forjado tiene las etiquetas Oscuridad o Ritual, te cura toda la salud cuando completas un ritual",
  "components.cursed-rosary.name": "Rosario maldito",
  "components.cursed-seal.desc": "Al recoger:\nLanza Sellar Destino sobre todos los enemigos en tu línea de visión",
  "components.cursed-seal.name": "Sello maldito",
  "components.defiled-reliquary.desc": "Al recoger:\nInvoca un Relicario Profanado cerca\nCada turno, inflige 10 de daño de Oscuridad o Sagrado a los enemigos en un radio de 5 casillas",
  "components.defiled-reliquary.name": "Relicario profanado",
  "components.devil-s-blood.desc": "Al recoger:\nRoba 2 PV máximos a cada Demonio en la línea de visión",
  "components.devil-s-blood.name": "Sangre del diablo",
  "components.discarded-homunculi.desc": "Al forjar:\nSi el equipo forjado tiene el atributo num_summons, obtiene +2 num_summons",
  "components.discarded-homunculi.name": "Homúnculos descartados",
  "components.dragon-ambrosia.desc": "Al forjar:\nSi el equipo forjado tiene la etiqueta Dragón, otorga +1 carga máxima a todos los hechizos de Dragón por cada hechizo de Dragón que conozcas",
  "components.dragon-ambrosia.name": "Ambrosía de dragón",
  "components.dragontongue-tablet.desc": "Al recoger:\nObtienes 1 SP si conoces un hechizo de Dragón",
  "components.dragontongue-tablet.name": "Tablilla de lengua de dragón",
  "components.drakentooth.desc": "Al recoger:\nInvoca un par de Dracos de Fuego para que luchen por ti",
  "components.drakentooth.name": "Diente de dragón",
  "components.dreamthorn-vine.desc": "Al recoger:\nEl enemigo más cercano queda aturdido durante 6 turnos y lanzas Prisión de Espinas sobre él",
  "components.dreamthorn-vine.name": "Enredadera de espinas oníricas",
  "components.eidolon-s-strings.desc": "Al recoger:\nLos enemigos Arcanos quedan enfurecidos durante 12 turnos",
  "components.eidolon-s-strings.name": "Cuerdas del eidolón",
  "components.elemental-ice.desc": "Al recoger:\nObtén 7 de SH",
  "components.elemental-ice.name": "Hielo elemental",
  "components.enchanter-s-awl.desc": "Al forjar:\nSi el equipo forjado tiene la etiqueta Encantamiento, esto vuelve a tu inventario después de usarse",
  "components.enchanter-s-awl.name": "Punzón del encantador",
  "components.familiar-s-collar.desc": "Al forjar:\nCuando el equipo forjado invoque una unidad, paga 3 PV para dejarla Vinculada al Alma con el mago",
  "components.familiar-s-collar.name": "Collar del familiar",
  "components.flame-blade-fragment.desc": "Al forjar:\nEl equipo forjado otorga una bonificación de +3 de daño a los hechizos y al equipo de cada una de sus etiquetas",
  "components.flame-blade-fragment.name": "Fragmento de hoja llameante",
  "components.frost-core.desc": "Al recoger:\nInflige 10 de daño de Hielo y 3 turnos de congelación a los enemigos en un radio de 2 casillas\nCada vez que este efecto se repite, su radio aumenta en 1\nEste efecto se repite cada 6 turnos hasta el final del nivel",
  "components.frost-core.name": "Núcleo de escarcha",
  "components.frostpetal.desc": "Al recoger:\nObtienes un 75% de resistencia a Hielo y regeneras 3 PV por turno durante 25 turnos",
  "components.frostpetal.name": "Pétalo de escarcha",
  "components.frozen-heartwood.desc": "Al recoger:\nInflige 50 de daño de Hielo y 6 turnos de congelación a los enemigos en un radio de 5 casillas\nLos aliados se curan en su lugar",
  "components.frozen-heartwood.name": "Duramen congelado",
  "components.fulminite-shard.desc": "Al recoger:\nLanza Cadena de Rayos apuntando al primer enemigo que te inflija daño cada turno durante el resto del nivel",
  "components.fulminite-shard.name": "Fragmento de fulminita",
  "components.glacial-script.desc": "Al recoger:\nLanza tus hechizos de Hielo dirigidos a ti mismo",
  "components.glacial-script.name": "Escritura glacial",
  "components.golden-dragonscale.desc": "Al recoger:\nInflige 10 de daño Sagrado a los enemigos que te dañen durante el resto del nivel",
  "components.golden-dragonscale.name": "Escama dorada de dragón",
  "components.hag-heart.desc": "Al recoger:\nInflige 1 de daño de Oscuridad a todas las demás unidades Vivas en la línea de visión\nCúrate por el daño infligido de esta manera\nEste efecto se repite cada turno hasta el final del nivel",
