  "components.hellbloom.desc": "Al recoger:\nInvoca 9 Sabuesos Infernales aliados que aparecen en ubicaciones aleatorias",
  "components.hellbloom.name": "Flor infernal",
  "components.holy-icon.desc": "Al recoger:\nInvoca a un Falso Profeta para que luche por ti",
  "components.holy-icon.name": "Icono sagrado",
  "components.holy-water.desc": "Al recoger:\nElimina todas las desventajas de ti mismo\nObtienes un 75% de resistencia a Oscuridad y Fuego que dura el resto del nivel",
