  "components.lost-ring.name": "Anillo perdido",
  "components.luminous-threads.desc": "Al forjar:\nSi el equipo forjado otorga resistencias al portador, otorga SH igual a tu maestría en Sagrado al comienzo de cada nivel",
  "components.luminous-threads.name": "Hilos luminosos",
  "components.magic-rune.desc": "Al recoger:\nLos hechizos y el equipo de Hechicería obtienen +6 de daño durante 15 turnos",
  "components.magic-rune.name": "Runa mágica",
  "components.mirror-stone.desc": "Al recoger:\nObtienes una copia adicional de este componente",
  "components.mirror-stone.name": "Piedra espejo",
  "components.mithril-ore.desc": "Al forjar:\nSi el equipo forjado tiene el atributo de daño, inflige +9 de daño",
  "components.mithril-ore.name": "Mineral de mithril",
  "components.moonstone.desc": "Al recoger:\nInvoca un Lamasu aliado",
  "components.moonstone.name": "Piedra lunar",
  "components.mycelial-ooze.desc": "Al recoger:\nInvoca 5 Hongobombas Verdes aliados cerca\nCuando mueren, se invocan 3 Limos Verdes de sus cadáveres",
  "components.mycelial-ooze.name": "Baba micelial",
  "components.nacreous-cysts.desc": "Al recoger:\nObtén un 50% de probabilidad de invocar un Limo Verde aliado cada turno durante el resto del nivel",
  "components.nacreous-cysts.name": "Quistes nacarados",
  "components.odin-s-eye.desc": "Al forjar:\nPor cada una de las etiquetas del equipo forjado, lanza un hechizo de Ojo aleatorio dirigido a ti mismo que conozcas con esa etiqueta al comienzo de cada nivel",
  "components.odin-s-eye.name": "Ojo de Odín",
  "components.oozing-oculite.desc": "Al recoger:\nUno de tus hechizos obtiene permanentemente +1 de alcance",
  "components.oozing-oculite.name": "Oculita viscosa",
  "components.phoenix-feather.desc": "Al forjar:\nSi el equipo forjado tiene la etiqueta Fuego, te cura 1 PV cuando lanzas un hechizo de Fuego\nSi el equipo forjado tiene la etiqueta Sagrado, te cura 1 PV cuando lanzas un hechizo de Sagrado",
  "components.phoenix-feather.name": "Pluma de fénix",
  "components.planar-keystone.desc": "Al recoger:\nCrea una nueva Grieta bajo el mago",
  "components.planar-keystone.name": "Piedra angular planar",
  "components.polymath-s-palimpsest.desc": "Al forjar:\nSi el equipo forjado tiene la etiqueta Palabra en su receta, este objeto se devuelve a tu inventario después de usarse",
  "components.polymath-s-palimpsest.name": "Palimpsesto del polímata",
  "components.primordial-ooze.desc": "Al forjar:\nSi el equipo forjado tiene la etiqueta Limo, un hechizo aleatorio que conozcas obtiene la etiqueta Limo",
  "components.primordial-ooze.name": "Baba primordial",
  "components.quipu-saga.desc": "Al forjar:\nSi el equipo forjado tiene el atributo de daño, al final de cada nivel obtiene +1 de daño",
  "components.quipu-saga.name": "Saga del quipu",
  "components.raven-eye.desc": "Al recoger:\nCiega a todos los enemigos durante 6 turnos\nEste efecto se repite cada 12 turnos hasta el final del nivel",
  "components.raven-eye.name": "Ojo de cuervo",
  "components.relocator-beacon.desc": "Al recoger:\nTeletransporta un Orbe de Memoria o Componente aleatorio del nivel a tu inventario\nEste efecto se repite cada 3 turnos hasta el final del nivel",
  "components.relocator-beacon.name": "Baliza de reubicación",
  "components.retinal-jelly.desc": "Al recoger:\nInvoca una Baba de Aniquilación aliada",
  "components.retinal-jelly.name": "Gelatina retiniana",
  "components.rift-residue.desc": "Al recoger:\nUn hechizo de Translocación aleatorio que conozcas obtiene permanentemente +1 carga máxima",
  "components.rift-residue.name": "Residuo de grieta",
  "components.runed-vellum.desc": "Al recoger:\nTriplica la duración restante de cualquiera de tus beneficios actualmente activos",
  "components.runed-vellum.name": "Pergamino rúnico",
  "components.runic-fetish.desc": "Al recoger:\nLos enemigos en la línea de visión sufren Dolor Compartido, que vuelve a infligir a las demás unidades el daño infligido a una de ellas",
  "components.runic-fetish.name": "Fetiche rúnico",
  "components.sacrificial-brand.desc": "Al recoger:\nObtienes PV máximos equivalentes a tu maestría en Sangre",
  "components.sacrificial-brand.name": "Marca sacrificial",
  "components.sanctified-locket.desc": "Al recoger:\nNo-muertos, Demonios y unidades de Oscuridad en la línea de visión quedan aterrorizados durante 8 turnos",
  "components.sanctified-locket.name": "Relicario santificado",
  "components.scripted-cortex.desc": "Al recoger:\nUn hechizo Arcano o de Palabra aleatorio que conozcas obtiene permanentemente +2 cargas máximas",
  "components.scripted-cortex.name": "Corteza inscrita",
  "components.seer-s-orb.desc": "Al recoger:\nOtorga +6 de alcance y elimina el requisito de línea de visión para lanzar todos los hechizos durante 10 turnos",
  "components.seer-s-orb.name": "Orbe del vidente",
  "components.shadeweave.desc": "Al recoger:\nTe curas una cantidad igual a tu maestría en Oscuridad cada turno hasta el final del nivel",
  "components.shadeweave.name": "Tejido de sombras",
  "components.shielding-shard.desc": "Al recoger:\nObtienes 1 SH por turno durante 15 turnos",
  "components.shielding-shard.name": "Fragmento protector",
  "components.shimmersteel.desc": "Al recoger:\nLos hechizos y el equipo Metálico obtienen +100% de daño y alcance hasta el final del nivel",
  "components.shimmersteel.name": "Acero centelleante",
  "components.silver-dragonscale.desc": "Al recoger:\nObtén un 50% de resistencia Física y un 100% de resistencia al Hielo durante el resto del nivel",
