  "components.slime-core.desc": "Al recoger:\nInvoca un trío de Limos del Vacío aliados",
  "components.slime-core.name": "Núcleo de limo",
  "components.starfire-ingot.desc": "Al recoger:\nInvoca un par de Quimeras de Fuego Estelar para luchar por ti",
  "components.starfire-ingot.name": "Lingote de fuego estelar",
  "components.stormglass-eye.desc": "Al recoger:\nInvoca una Nube de Tormenta sobre cada enemigo en la línea de visión\nCada nube tiene un 50% de probabilidad de infligir 25 de daño de Rayo cada turno\nLas Nubes de Tormenta duran 5 turnos\nEste efecto se repite cada 6 turnos hasta el final del nivel",
  "components.stormglass-eye.name": "Ojo de cristal de tormenta",
  "components.stormsong-note.desc": "Al forjar:\nSi el equipo forjado tiene la etiqueta Hielo, invoca Ventiscas en ubicaciones aleatorias cuando lanzas manualmente un hechizo de Hielo\nSi el equipo forjado tiene la etiqueta Rayo, invoca Nubes de Tormenta en ubicaciones aleatorias cuando lanzas manualmente un hechizo de Rayo\nLa cantidad de nubes creadas es igual al nivel del hechizo\nEl daño y la duración de las nubes escalan con el equipo",
  "components.stormsong-note.name": "Nota del canto de tormenta",
  "components.thundergod-s-fang.desc": "Al recoger:\nLos enemigos con la etiqueta Rayo y menos PV que tú se unen a tu equipo",
  "components.thundergod-s-fang.name": "Colmillo del dios del trueno",
  "components.timelost-inscription.desc": "Al recoger:\nDurante los próximos 6 turnos, cuando lances un hechizo de Hechicería, cada uno de tus otros hechizos recupera una carga",
  "components.timelost-inscription.name": "Inscripción perdida en el tiempo",
  "components.umbral-resin.desc": "Al recoger:\nObtén un 100% de resistencia al daño de Oscuridad y Veneno durante el resto del nivel",
  "components.umbral-resin.name": "Resina umbría",
  "components.voidstone-shard.desc": "Al recoger:\nRecupera todas las cargas de hechizos",
  "components.voidstone-shard.name": "Fragmento de piedra del vacío",
  "components.voltaic-ash.desc": "Al recoger:\nDispara un haz hacia cada otra unidad en tu línea de visión\nCada haz inflige 16 de daño de Fuego o Rayo\nEste efecto se repite cada 6 turnos hasta el final del nivel",
  "components.voltaic-ash.name": "Ceniza voltaica",
  "components.votive-candle.desc": "Al recoger:\nCura 10 PV por turno durante los próximos 12 turnos",
  "components.votive-candle.name": "Vela votiva",
  "components.warlord-s-skull.desc": "Al forjar:\nSi el equipo forjado otorgara bonificaciones de daño, duración, alcance o número de objetivos, otorga esas bonificaciones a daño de esbirros, duración de esbirros, alcance de esbirros o número de invocaciones en su lugar",
  "components.warlord-s-skull.name": "Cráneo del señor de la guerra",
  "components.warped-dragon-egg.desc": "Al recoger:\nUn hechizo de Conjuración aleatorio que conozcas obtiene +3 de daño de esbirros",
  "components.warped-dragon-egg.name": "Huevo de dragón distorsionado",
  "components.watcher-stone.desc": "Al recoger:\nInvoca un Vigilante aliado",
  "components.watcher-stone.name": "Piedra del vigilante",
  "components.wildflower.desc": "Al recoger:\nElimina el veneno y te cura 50 PV",
  "components.wildflower.name": "Flor silvestre",
  "components.worldstone-socket.desc": "Al forjar:\nSi el equipo forjado tiene el atributo de radio, obtiene +2 de radio",
  "components.worldstone-socket.name": "Engaste de la piedra del mundo",
