  "equipment.timestriders.name": "Caminatiempos",
  "equipment.titan-s-bane.desc": "Cuando lanzas manualmente un hechizo de Hechicería contra un gigante, lánzalo de nuevo\nCualquier unidad que ocupe más de una casilla se considera un gigante",
  "equipment.titan-s-bane.name": "Perdición del Titán",
  "equipment.travellers-shoes.name": "Zapatos de Viajero",
  "equipment.treelord-staff.desc": "Cuando lanzas un hechizo de Naturaleza de nivel 3 o superior, invoca un Ent cerca",
  "equipment.treelord-staff.name": "Bastón del Señor de los Árboles",
  "equipment.tundra-mantle.desc": "Cada turno, los enemigos empapados en un radio de 5 casillas quedan congelados durante 3 turnos",
  "equipment.tundra-mantle.name": "Manto de Tundra",
  "equipment.twilight-lantern.desc": "Cuando lanzas un hechizo de Oscuridad o Sagrado, obtienes Centinela del crepúsculo con una duración igual al nivel del hechizo\nCentinela del crepúsculo inflige 6 de daño de Oscuridad a un enemigo aleatorio en tu línea de visión cada turno, y luego 6 de daño Sagrado a otro",
  "equipment.twilight-lantern.name": "Linterna del crepúsculo",
  "equipment.twilight-oculus.desc": "La primera vez que un enemigo recibe daño de Oscuridad o Sagrado, obtiene -25 de resistencia a Oscuridad y Sagrado",
  "equipment.twilight-oculus.name": "Óculo del Crepúsculo",
  "equipment.tzango-s-cleaver.desc": "Al comienzo de cada nivel, lanza Choque mortal sobre hasta 2 enemigos adyacentes aleatorios",
  "equipment.tzango-s-cleaver.name": "Cuchilla de Tzango",
  "equipment.umbral-totem.name": "Tótem umbral",
  "equipment.unblinking-eye.name": "Ojo Que No Parpadea",
  "equipment.unholy-expurgator.desc": "Los aliados Oscuridad y Sagrado aprenden Expurgar\nExpurgar es un hechizo cuerpo a cuerpo\nExpurgar inflige 8 de daño de Oscuridad, Sagrado y Físico\nExpurgar tiene 3 turnos de enfriamiento",
  "equipment.unholy-expurgator.name": "Expurgador Profano",
  "equipment.vampiric-vestments.desc": "Cuando muere una unidad Viva, cura 5 PV",
  "equipment.vampiric-vestments.name": "Vestimentas Vampíricas",
  "equipment.veilpiercer-s-monocle.desc": "Obtienes claridad al lanzar un hechizo de Translocación\nLa duración de la mejora es igual al nivel del hechizo",
  "equipment.veilpiercer-s-monocle.name": "Monóculo del Perforavelos",
  "equipment.venom-spitter-casque.desc": "Los aliados Vivo y Naturaleza aprenden Escupitajo de Veneno\nEscupitajo de Veneno inflige 4 de daño de Veneno y aplica Veneno durante 10 turnos\nEscupitajo de Veneno tiene 3 de alcance y 3 turnos de enfriamiento",
  "equipment.venom-spitter-casque.name": "Yelmo Escupidor de Veneno",
  "equipment.venomancer-s-vial.desc": "Los enemigos envenenados reciben 4 de daño de Veneno adicional cada turno",
  "equipment.venomancer-s-vial.name": "Frasco del Venomante",
  "equipment.vial-of-ambrosia.desc": "Al principio de cada nivel, obtén 10 turnos de Claridad",
  "equipment.vial-of-ambrosia.name": "Vial de Ambrosía",
  "equipment.vile-dagger.name": "Daga Vil",
  "equipment.void-hunter-s-sigil.desc": "Por cada unidad Arcana que muera, uno de tus hechizos Arcanos recupera 1 carga\nAl final de cada nivel, se crea una Grieta que contiene enemigos Arcanos",
  "equipment.void-hunter-s-sigil.name": "Sigilo del Cazador del Vacío",
  "equipment.void-oculus.desc": "La primera vez que un enemigo recibe daño de Oscuridad o Arcano, obtiene -25 de resistencia a Oscuridad y Arcano",
  "equipment.void-oculus.name": "Óculo del Vacío",
  "equipment.void-spike-stone.desc": "Cuando tú o uno de tus aliados Arcano o No-muerto recibe daño de un enemigo, inflige 5 de daño de Arcano al enemigo",
  "equipment.void-spike-stone.name": "Piedra de Púa del Vacío",
  "equipment.void-traveler-s-cloak.desc": "Cuando te teletransportas, obtén 2 de SH",
  "equipment.void-traveler-s-cloak.name": "Capa del Viajero del Vacío",
  "equipment.voidflame-lantern.desc": "Al lanzar un hechizo de Fuego o Arcano, obtienes Carga Estelar con una duración igual al nivel del hechizo\nCarga Estelar inflige 6 de daño Arcano a un enemigo aleatorio en línea de visión cada turno y luego 6 de daño de Fuego a otro",
  "equipment.voidflame-lantern.name": "Linterna de Llama del Vacío",
  "equipment.volcanic-lance.desc": "Cuando lanzas un hechizo de Fuego apuntando a un enemigo, lanza un rayo destructivo hacia el objetivo\nEl rayo destruye muros e inflige daño de Fuego equivalente a tu maestría de Fuego",
  "equipment.volcanic-lance.name": "Lanza Volcánica",
  "equipment.voodoo-doll.desc": "Al comienzo de cada nivel, los 5 enemigos con más PV quedan Atados por Vudú\nCuando recibes daño, los enemigos Atados por Vudú reciben ese daño\nCuando gastas PV, Atados por Vudú inflige esa misma cantidad de daño Físico a los enemigos",
  "equipment.voodoo-doll.name": "Muñeco de Vudú",
  "equipment.warlord-banner.name": "Estandarte del Señor de la Guerra",
  "equipment.warlord-helm.name": "Yelmo del Señor de la Guerra",
  "equipment.warlord-vestments.name": "Vestimentas del Señor de la Guerra",
  "equipment.wild-healing-staff.desc": "Cuando lanzas un hechizo de Naturaleza, tú y tus aliados Vivo se curan 5 PV",
  "equipment.wild-healing-staff.name": "Bastón de Curación Salvaje",
  "equipment.winged-shoes.desc": "Otorga Vuelo",
  "equipment.winged-shoes.name": "Zapatos Alados",
  "equipment.winter-links.desc": "Cuando un enemigo muere por daño de Hielo u Oscuridad, un enemigo aleatorio en su línea de visión a un máximo de 3 casillas recibe 9 de daño de ese tipo",
  "equipment.winter-links.name": "Vínculos del Invierno",
  "equipment.wintersting.desc": "Por cada 80 de daño infligido a enemigos por hechizos o equipo de Hielo, lanza Aguijón Venenoso sobre un enemigo aleatorio\nDaño Infligido: 0",
  "equipment.wintersting.name": "Aguijón Invernal",
  "equipment.witching-hourglass.desc": "Cuando un enemigo despierta del sueño, invoca un Fantasma temporal cerca de él",
  "equipment.witching-hourglass.name": "Reloj de Arena Brujo",
  "equipment.woadwyrd.desc": "Por cada 100 de daño infligido a enemigos por hechizos o equipo de Naturaleza, lanza Maleficio Sombrío sobre un enemigo aleatorio\nDaño Infligido: 0",
  "equipment.woadwyrd.name": "Hado Índigo",
  "equipment.wound-rot-amulet.desc": "Los enemigos reciben 3 turnos de veneno cuando reciben daño Físico",
  "equipment.wound-rot-amulet.name": "Amuleto de Putrefacción de Heridas",
  "equipment.wrath-links.desc": "Cuando un enemigo muere por daño Sagrado o de Rayo, un enemigo aleatorio en su línea de visión a un máximo de 3 casillas recibe 9 de daño de ese tipo",
  "equipment.wrath-links.name": "Vínculos de la Ira",
  "equipment.wyrm-spirit-armor.desc": "Cuando muere uno de tus aliados Dragón, obtienes 10% de resistencia a los tipos de daño que coincidan con sus etiquetas\nSe reinicia en cada nivel",
  "equipment.wyrm-spirit-armor.name": "Armadura del Espíritu de Wyrm",
