  "passives.01493490": "Cura a los aliados en un radio de 7 casillas en 3 cada turno",
  "passives.028e0cb0": "Cada turno, 10% de probabilidad de teletransportarse a una casilla aleatoria a hasta 8 casillas de distancia",
  "passives.0320ee32": "Al infligir daño, obtiene 1 de PV máximo y 1 de daño en hechizos",
  "passives.075a4c5a": "Tiene un 10% de probabilidad cada turno de generar 2 Crías de Araña del Éter",
  "passives.0795ee34": "Al morir, inflige 25 de daño de Fuego en un estallido de 4 casillas, curando a los aliados en su lugar",
  "passives.08af9705": "Cada turno, 2% de probabilidad de convertirse en un Árbol Cerebral",
  "passives.08f0f031": "Libera 3 espíritus malignos al ser destruida",
  "passives.0ab18fa7": "Gana 1 SH cada 9 turnos hasta un máximo de 9",
  "passives.0c4a19a5": "Cada turno, el Orbe de Anima cura hasta a 2 aliados heridos en su línea de visión\n\nEl Orbe de Anima usa sus propios PV para curar a sus aliados e intentará curarlos hasta su salud máxima",
  "passives.0c4e6051": "Cada turno, 50% de probabilidad de curar el 10% de los PV máximos originales\nEl exceso aumenta los PV máximos\n\nAl alcanzar el doble de los PV máximos originales, se divide en 2 Gelguts",
  "passives.0c80fda0": "Al morir, invoca 3 Limos Verdes",
  "passives.0d775044": "Cada turno, inflige 3 de daño de Rayo a enemigos a 2 casillas o menos",
  "passives.0dd7da33": "Reencarna al morir (9 veces)",
  "passives.0dfc0033": "Cuando muere una unidad, gana +1 de daño de hechizo",
  "passives.11a39fb5": "Cura 100 PV cada turno",
  "passives.11d0d481": "Cada turno, otorga 1 SH a los aliados adyacentes sin escudo",
  "passives.12252e1b": "Gana 2 de SH cada turno",
  "passives.1233ec03": "Cada turno, inflige 3 de daño de Oscuridad o Fuego a los enemigos en un radio de 6 casillas",
  "passives.13a6d609": "Cada turno, 50% de probabilidad de curar un 10% de los PV máximos originales\nEl exceso aumenta los PV máximos\n\nAl doble de los PV máximos originales, se divide en 2 limos",
  "passives.13e13a0f": "Al recibir daño, aturde a la fuente durante 2 turnos",
  "passives.13f4f5ed": "Al morir, invoca un León de Hielo y una Serpiente de la Muerte",
  "passives.14cb78be": "Reencarna al morir (1 vez)",
  "passives.16ebffec": "Gana 1 SH cada 1 turno hasta un máximo de 8",
  "passives.18c0763e": "Al morir, invoca un León Estelar y una Serpiente de Fuego",
  "passives.19b60d35": "Cura 1 de PV cada vez que una unidad recibe daño de Sangrado",
  "passives.19da76e1": "Cada turno, inflige 3 de daño de Oscuridad o Veneno a las unidades en un radio de 3 casillas",
  "passives.1a65ebfb": "Al recibir daño, 30% de probabilidad de infligir 16 de daño Físico a todas las unidades a 4 casillas o menos",
  "passives.1b950c08": "Obtiene 1 SH cada turno",
  "passives.1e5ae37c": "Al llegar a 0 PV, se transforma en un Ojo Vampiro",
  "passives.2017d6e9": "Al morir, invoca 8 Goblins",
  "passives.2035061d": "Al recibir daño, obtiene esa misma cantidad de resistencia a ese tipo de daño y +1 de daño en todos los hechizos",
  "passives.21e04ff4": "No puede perder más de 700 PV en un turno",
  "passives.22e383aa": "Al morir, aplica Veneno a las unidades adyacentes durante 12 turnos",
  "passives.23ea3949": "Cada turno, 80% de probabilidad de parpadear a una casilla aleatoria a hasta 6 casillas de distancia",
  "passives.23f216a7": "Cada turno, se vuelve vulnerable a un tipo de daño diferente",
  "passives.253b93dd": "Cuando un enemigo sufre daño de Hielo, tiene un 50% de probabilidad de quedar congelado durante 1 turno",
  "passives.2624028c": "Regenera 5 PV cada turno\nSe desactiva al recibir daño de Fuego",
  "passives.2659d32f": "Cuando un aliado Vivo muere, se teletransporta a su ubicación y realiza un turno adicional",
  "passives.269c7bd9": "Al morir, inflige 5 de daño de Oscuridad a las unidades a un máximo de 1 casilla",
  "passives.26c0cea9": "Cada turno, 50% de probabilidad de destellar a una casilla aleatoria a hasta 10 casillas de distancia",
  "passives.274908ae": "Vuelve a infligir todo el daño que no sea de Veneno infligido a los enemigos como daño de Veneno",
  "passives.28794cd9": "Cada turno, inflige 3 de daño de Hielo a los enemigos a hasta 4 casillas",
  "passives.2883fc8a": "Cada turno, inflige 1 de daño de Fuego a los enemigos en un radio de 4 casillas",
  "passives.29797228": "Al morir, aplica Hemorragia a las unidades adyacentes durante 10 turnos",
  "passives.2b23352b": "Recoge una extremidad cada vez que da un paso o muere una unidad adyacente\n\nTras recoger 4 extremidades, se genera un Deambulador de Huesos cerca",
  "passives.2bd9bf63": "Al recibir daño, inflige ese daño a enemigos en la línea de visión",
  "passives.2cb1c342": "Inflige Infestado de Larvas al asesino durante 10 turnos",
  "passives.2cd42f0f": "Invoca 40 Elementales de Tierra cuando los PV caen por debajo del 75%",
  "passives.2cfc30bc": "Al llegar a 0 PV, se transforma en una Reina Avispón Calavera",
  "passives.2deb729a": "Cada turno, inflige 2 de daño de Fuego a enemigos a 7 casillas o menos",
  "passives.2e14f9f8": "Los enemigos quedan asustados durante un turno cuando reciben daño Arcano",
  "passives.302df702": "Inflige 1 de daño de Oscuridad a atacantes cuerpo a cuerpo",
  "passives.30dcc880": "Gana 1 SH cada 3 turnos, hasta un máximo de 2",
  "passives.31dcca13": "Gana 1 SH cada 3 turnos hasta un máximo de 3",
  "passives.3360bb7a": "Cuando un aliado muere, intenta teletransportarse cerca del asesino y toma un turno extra",
  "passives.350b1531": "Tiene un 10% de probabilidad cada turno de generar una Bestia Desplazadora",
  "passives.355c13d7": "Cada turno, los enemigos en un radio de 3 casillas reciben 8 de daño de Hielo y quedan congelados durante 3 turnos\nCuando una unidad congelada dentro del radio muere por daño de Hielo, crea un muro en su casilla",
