  "passives.eb427d00": "Gana 5 PV máximos cada vez que se lanza un hechizo de Rayo en la línea de visión",
  "passives.eb6b8c8a": "Cuando esta unidad pierde un escudo, invoca un Hamsa Ilusorio temporal\nLos Hamsas Ilusorios están Vinculados al Alma de esta unidad",
  "passives.ec5f277e": "Cura en 3 a los aliados en un radio de 5 casillas cada turno",
  "passives.ed39a8f0": "Cada turno, 2% de probabilidad de convertirse en un Zombi putrefacto",
  "passives.f04ab146": "Al llegar a 0 PV, se transforma en un Murciélago vampiro",
  "passives.f05be0fc": "Cada turno, los aliados en un radio de 3 casillas realizan un turno adicional\nNo afecta a los Visitantes Angelicales",
  "passives.f0b94da2": "Redirige todo el daño hacia los aliados",
  "passives.f10e8312": "Al morir, otorga Celeridad a los aliados",
  "passives.f16073c8": "Inflige 6 de daño Físico a atacantes cuerpo a cuerpo",
  "passives.f167fac8": "Explosión Suicida",
  "passives.f19872ff": "Cuando es objetivo de un hechizo enemigo, lanza Rayo en Cadena sobre el lanzador",
  "passives.f229e6d0": "Cada turno, 50% de probabilidad de parpadear a una casilla aleatoria a hasta 4 casillas de distancia",
  "passives.f2afe5c0": "Al morir, invoca un León de Fuego y una Serpiente de Rayo",
  "passives.f2dcbecf": "Cuando un enemigo lanza un hechizo, inflige 10 turnos de sangrado",
  "passives.f3ade82b": "Cada turno, inflige 3 de daño de Fuego o Sagrado a los enemigos en un radio de 4 casillas",
  "passives.f3c2589d": "Cura 10 PV cada turno\nEl exceso aumenta los PV máximos\nAl recibir daño, invoca un Limo de Sangre",
  "passives.f3e1e173": "Cura 3 PV cada turno",
  "passives.f54c9fa0": "Consume al aliado con menos PV cada turno, infligiendo 20 de daño de Fuego a los enemigos en un radio de 3 casillas\nEn su lugar, los aliados en la explosión son curados",
  "passives.f5f3bcfe": "Inflige Sangrado a los atacantes enemigos cuerpo a cuerpo durante 4 turnos",
  "passives.f68d26a3": "Cada turno, extiende la duración del veneno en los enemigos envenenados en 1 turno\n\nCada turno, aplica 2 turnos de veneno a los enemigos no envenenados",
  "passives.f71ded02": "Cada turno, inflige 4 de daño de Fuego a los enemigos a 16 casillas o menos",
  "passives.f9485801": "Al recibir daño, invoca una Serpiente cerca",
  "passives.f9b52bf0": "Al morir, invoca 6 Globos Oculares Flotantes",
  "passives.f9dad53b": "Al morir, invoca un Gnomo Donsy",
  "passives.fa29eb8f": "Al morir, invoca a 3 Atormentadores de Fuego Gélido",
  "passives.fb5ab453": "Cada turno, consume cualquier nube adyacente\nCura 10 PV por cada nube devorada.",
  "passives.fbfe24d4": "Tiene un 10% de probabilidad cada turno de generar 2 Crías de Araña de Acero",
  "passives.fc8d97f9": "Cada turno, inflige 16 de daño de Fuego a los enemigos en un alcance de 7 casillas",
  "passives.fce5e4c8": "Cuando un aliado No-muerto muere, gana una acumulación de Furia Sangrienta",
  "passives.fee99432": "Tiene un 20% de probabilidad cada turno de generar un Bombardero de Hielo",
  "passives.ff1f9106": "Cada turno, inflige 20 de daño de Fuego a enemigos en haces que se extienden en las cuatro direcciones cardinales",
  "passives.ff63a290": "Reencarna al morir (2 veces)",
